"""Автономный отчёт отделяет внутренний выбор правил от внешней диагностики."""
import json

NAMES = {"conditional": ("Обучаемый условный оператор", "Fitted conditional operator"),
         "age_majority": ("Большинство на той же паре возрастов", "Same-age-pair majority"),
         "previous_unanimous": ("Прежнее единогласие", "Previous unanimity"),
         "frequency": ("Частотная база", "Frequency baseline")}


def markdown(data):
    sealed, e = data["sealed"], data["evaluation"]
    lines = ["# Условный оператор: вложенный выбор условий переноса", "",
             "**Улучшение не показано. Новых научных предсказаний: 0. Критерий предсказания последующей статьи не достигнут.**", "",
             "| Режим | Выдано / всего | Совпало | Ошибок | Отказов | Точность выданных |",
             "|---|---:|---:|---:|---:|---:|"]
    for mode, m in e["modes"].items():
        accuracy = f'{100*m["accuracy_among_issued"]:.1f}%' if m["issued"] else "—"
        lines.append(f'| {NAMES[mode][0]} | {m["issued"]}/{m["queries"]} | {m["matched"]} | {m["wrong_order"]} | {m["abstained"]} | {accuracy} |')
    lines += ["", "## Сравнение на одинаковых случаях", ""]
    for mode, p in e["paired"].items():
        lines.append(f'- {NAMES[mode][0]}: общих выданных случаев {p["queries"]}; условный оператор — {p["conditional_matched"]} совпадений, база — {p["baseline_matched"]}; одинаковых прогнозов {p["same_predictions"]}.')
    lines += ["", "## Как выбраны условия", "",
        "Сетка из 12 вариантов зафиксирована в коде до этого прогона: 6 наборов обязательных контекстных полей × 2 правила голосования. Наборы: без фильтра; критерий диагностики; порог SD; критерий + SD + исключение деменции; нормы; вид наблюдения (средний или максимальный срок). Участники, числа, возрастные интервалы и остальные контексты сохраняются. Неизвестное обязательное поле не разрешает совпадение.", "",
        "Один голос на группу происхождения. Совместно используются две числовые возрастные оценки одного исхода одного исследования. Единогласие требует отсутствия разногласий; большинство — ≥2/3 всех подходящих групп, включая смешанные как не поддерживающие конкретное направление. Минимум две группы с определёнными голосами. Всегда совпадают исход, мера, единицы, дизайн и точная пара соседних возрастов.", "",
        "На каждом внешнем разбиении выполняется внутреннее исключение целых групп только из оставшегося обучения. Оценка варианта — среднее по внутренним группам `(совпадения − 2 × ошибки) / все запросы`; отказ даёт 0. Это выбранная диагностическая цена ошибки, не универсальная научная метрика. Вариант должен выдать хотя бы один ответ минимум для двух внутренних групп. При равенстве выбираются большее покрытие, меньше условий, единогласие и стабильный id. Если допустимого варианта нет — отказ, без запуска другого способа прогнозирования.", "",
        "Выбор один для всего внешнего обучающего разбиения, а не отдельная настройка по скрытому исходу. Внешние контексты и исходы не участвуют в выборе. В журнале сохранены все внутренние разбиения, свидетельства и оценки всех 12 вариантов.", "",
        "| Внешнее разбиение | Исключённая группа | Выбранный вариант |", "|---|---|---|"]
    for f in sealed["folds"]:
        selected = f["selection"]["selected"]
        lines.append(f'| {f["fold_id"]} | {f["withheld_family"]} | {selected["id"] if selected else "отказ"} |')
    rows = {r["query_id"]: r for r in e["modes"]["previous_unanimous"]["rows"]}
    changed = [r for r in e["modes"]["conditional"]["rows"] if r["predicted_order"] != rows[r["query_id"]]["predicted_order"]]
    lines += ["", "## Изменения относительно прежнего оператора", ""]
    for r in changed:
        lines.append(f'- `{r["query_id"]}`: прежний прогноз `{rows[r["query_id"]]["predicted_order"]}`, условный `{r["predicted_order"]}`; опубликованный порядок `{r["reported_order"]}`.')
    lines += ["", "Добавленный фильтр не исправил четыре прежние ошибки. Это не доказательство бесполезности контекста: на данной сетке и малом наборе устойчивое улучшение не получено. Точную причину неудачи эти результаты не устанавливают.", "",
        "## Границы опыта", "",
        "Используются те же 45 возрастных оценок заболеваемости из таблицы 2 обзора PMC6416157: 7 публикаций, 13 рядов и 6 консервативных групп происхождения. Busse 2003 и Luck 2010 удаляются вместе, включая подтипы MCI. Первичная независимость групп не подтверждена экспертно. Все пять карт проверены; числовой материал происходит из одной обзорной статьи. Первичные полные тексты сейчас не открывались.", "",
        "Прогнозируется порядок опубликованных точечных оценок на 1000 человеко-лет, не сами числа, причинность, индивидуальное старение, значимость различий или истинный популяционный эффект. Перекрытие интервалов не доказывает отсутствие разницы. Метрики считаются по запросам; это не 32 независимых исследования. Временного разделения публикаций нет.", "",
        "Прогнозный процесс читает только манифест и шесть разбиений без числовых ячеек внешней группы. Все прогнозы фиксируются до открытия контролей оценщиком. Но исходы были просмотрены ранее, поэтому вложенная вычислительная изоляция не делает этот опыт слепым или независимым научным подтверждением. Codex подготовил материал; экспертная проверка отсутствует. Целевая PMC10000452 не загружалась.", "",
        "## Что делать дальше", "",
        "На этом наборе повторный подбор фильтров создаёт риск переобучения к уже известным результатам. Следующая проверка требует первичных исследований с проверенной независимостью и вариацией методов и исходов. Нужно заранее выделить новый контрольный источник, оставить его результаты закрытыми, зафиксировать допустимые операторы и цену ошибок, обучать условия только на прежних источниках и сопоставлять с базами на общем покрытии. Эта сетка и её отрицательный результат сохранены как контрольная точка разработки.", "",
        f'Запуск `{sealed["run_id"]}`; оценка `{e["evaluation_id"]}`.', "",
        "Пройдено 100 Python-тестов, включая искусственный контроль обучения противоположным направлениям по диагностическому контексту. Искусственный контроль показывает способность алгоритма к выбору условия и не считается научным успехом. Модельных и сетевых вызовов нет. Карты, GOLD и прежние результаты сохранены; сервисы не менялись.", ""]
    return "\n".join(lines)


def render(data):
    payload = json.dumps(data, ensure_ascii=False, allow_nan=False).replace("<", "\\u003c").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    return HTML.replace("__DATA__", payload)


